CREATE TYPE "ChatProvider" AS ENUM ('SLACK','TEAMS');
CREATE TABLE "ChatConnection" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL,"projectId" TEXT,"provider" "ChatProvider" NOT NULL,"name" TEXT NOT NULL,"channelName" TEXT NOT NULL,"encryptedEndpoint" TEXT NOT NULL,"endpointFingerprint" TEXT NOT NULL,"events" TEXT[] NOT NULL,"detailLevel" TEXT NOT NULL DEFAULT 'STANDARD',"enabled" BOOLEAN NOT NULL DEFAULT true,"lastError" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChatConnection_workspaceId_fkey" FOREIGN KEY ("workspaceId") REFERENCES "Workspace"("id") ON DELETE CASCADE);
CREATE INDEX "ChatConnection_workspaceId_enabled_idx" ON "ChatConnection"("workspaceId","enabled");
CREATE INDEX "ChatConnection_projectId_idx" ON "ChatConnection"("projectId");
CREATE TABLE "ChatDelivery" ("id" TEXT PRIMARY KEY,"connectionId" TEXT NOT NULL,"eventId" TEXT NOT NULL,"event" TEXT NOT NULL,"payload" JSONB NOT NULL,"status" "WebhookDeliveryStatus" NOT NULL DEFAULT 'PENDING',"attempts" INTEGER NOT NULL DEFAULT 0,"availableAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lockedAt" TIMESTAMP(3),"deliveredAt" TIMESTAMP(3),"responseStatus" INTEGER,"lastError" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ChatDelivery_connectionId_fkey" FOREIGN KEY ("connectionId") REFERENCES "ChatConnection"("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "ChatDelivery_connectionId_eventId_key" ON "ChatDelivery"("connectionId","eventId");
CREATE INDEX "ChatDelivery_status_availableAt_idx" ON "ChatDelivery"("status","availableAt");
CREATE INDEX "ChatDelivery_connectionId_createdAt_idx" ON "ChatDelivery"("connectionId","createdAt");
